'use strict';

// MODULES //

var reinterpret = require( '@stdlib/strided/base/reinterpret-complex128' );
var isRowMajor = require( '@stdlib/ndarray/base/assert/is-row-major' );
var real = require( '@stdlib/complex/float64/real' );
var imag = require( '@stdlib/complex/float64/imag' );


// MAIN //

/**
* Performs the hermitian rank 2 operation `A = alpha*x*y**H + conjg( alpha )*y*x**H + A`, where `alpha` is a scalar, `x` and `y` are `N` element vectors and `A` is an `N` by `N` hermitian matrix.
*
* @private
* @param {string} uplo - specifies whether `A` is an upper or lower triangular part of matrix is supplied.
* @param {NonNegativeInteger} N - number of elements along each dimension of `A`
* @param {Complex128} alpha - scalar
* @param {Complex128Array} x - first input array
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting `x` index
* @param {Complex128Array} y - second input array
* @param {integer} strideY - `y` stride length
* @param {NonNegativeInteger} offsetY - starting `y` index
* @param {Complex128Array} A - input matrix
* @param {integer} strideA1 - stride of the first dimension of `A`
* @param {integer} strideA2 - stride of the second dimension of `A`
* @param {NonNegativeInteger} offsetA - starting index for `A`
* @returns {Complex128Array} `A`
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
*
* var x = new Complex128Array( [ 1.0, 1.0, 1.0, 1.0 ] );
* var y = new Complex128Array( [ 1.0, 1.0, 1.0, 1.0 ] );
* var A = new Complex128Array( [ 1.0, 0.0, 0.0, 0.0, 2.0, 3.0, 4.0, 0.0 ] );
* var alpha = new Complex128( 1.0, 0.0 );
*
* zher2( 'lower', x.length, alpha, x, 1, 0, y, 1, 0, A, 2, 1, 0 );
* // A => <Complex128Array>[ 5.0, 0.0, 0.0, 0.0, 6.0, 3.0, 8.0, 0.0 ]
*/
function zher2( uplo, N, alpha, x, strideX, offsetX, y, strideY, offsetY, A, strideA1, strideA2, offsetA ) { // eslint-disable-line max-params, max-len
	var realpha;
	var imalpha;
	var retmp1;
	var imtmp1;
	var retmp2;
	var imtmp2;
	var viewX;
	var viewY;
	var viewA;
	var xre0;
	var xim0;
	var yre0;
	var yim0;
	var xre1;
	var xim1;
	var yre1;
	var yim1;
	var isrm;
	var idx;
	var ix1;
	var iy1;
	var ix0;
	var iy0;
	var re0;
	var im0;
	var re1;
	var im1;
	var sa0;
	var sa1;
	var re;
	var im;
	var i1;
	var i0;
	var ix;
	var iy;
	var ia;
	var sx;
	var sy;

	realpha = real( alpha );
	imalpha = imag( alpha );

	viewX = reinterpret( x, 0 );
	viewY = reinterpret( y, 0 );
	viewA = reinterpret( A, 0 );

	isrm = isRowMajor( [ strideA1, strideA2 ] );
	if ( isrm ) {
		sa0 = strideA2 * 2;
		sa1 = strideA1 * 2;
	} else {
		sa0 = strideA1 * 2;
		sa1 = strideA2 * 2;
	}
	ix = offsetX * 2;
	iy = offsetY * 2;
	ia = offsetA * 2;
	sx = strideX * 2;
	sy = strideY * 2;
	if ( ( isrm && uplo === 'upper' ) || ( !isrm && uplo === 'lower' ) ) {
		for ( i1 = 0; i1 < N; i1++ ) {
			ix1 = ix + ( i1 * sx );
			iy1 = iy + ( i1 * sy );
			xre0 = viewX[ ix1 ];
			xim0 = viewX[ ix1 + 1 ];
			yre0 = viewY[ iy1 ];
			yim0 = viewY[ iy1 + 1 ];
			for ( i0 = i1; i0 < N; i0++ ) {
				ix0 = ix + ( i0 * sx );
				iy0 = iy + ( i0 * sy );
				xre1 = viewX[ ix0 ];
				xim1 = viewX[ ix0 + 1 ];
				yre1 = viewY[ iy0 ];
				yim1 = viewY[ iy0 + 1 ];

				re0 = ( xre0 * yre1 ) + ( xim0 * yim1 );
				im0 = ( xim0 * yre1 ) - ( xre0 * yim1 );
				retmp1 = ( realpha * re0 ) - ( imalpha * im0 );
				imtmp1 = ( realpha * im0 ) + ( imalpha * re0 );

				re1 = ( yre0 * xre1 ) + ( yim0 * xim1 );
				im1 = ( yim0 * xre1 ) - ( yre0 * xim1 );
				retmp2 = ( realpha * re1 ) + ( imalpha * im1 );
				imtmp2 = ( realpha * im1 ) - ( imalpha * re1 );

				re = retmp1 + retmp2;
				im = imtmp1 + imtmp2;
				idx = ia + ( i0 * sa0 ) + ( i1 * sa1 );
				viewA[ idx ] += re;
				viewA[ idx + 1 ] += im;
				if ( i0 === i1 ) {
					viewA[ idx + 1 ] = 0.0;
				}
			}
		}
		return A;
	}
	// ( isrm && uplo === 'lower' ) || ( !isrm && uplo === 'upper' )
	for ( i1 = 0; i1 < N; i1++ ) {
		ix1 = ix + ( i1 * sx );
		iy1 = iy + ( i1 * sy );
		xre0 = viewX[ ix1 ];
		xim0 = viewX[ ix1 + 1 ];
		yre0 = viewY[ iy1 ];
		yim0 = viewY[ iy1 + 1 ];
		for ( i0 = 0; i0 <= i1; i0++ ) {
			ix0 = ix + ( i0 * sx );
			iy0 = iy + ( i0 * sy );
			xre1 = viewX[ ix0 ];
			xim1 = viewX[ ix0 + 1 ];
			yre1 = viewY[ iy0 ];
			yim1 = viewY[ iy0 + 1 ];

			re0 = ( xre0 * yre1 ) + ( xim0 * yim1 );
			im0 = ( xim0 * yre1 ) - ( xre0 * yim1 );
			retmp1 = ( realpha * re0 ) - ( imalpha * im0 );
			imtmp1 = ( realpha * im0 ) + ( imalpha * re0 );

			re1 = ( yre0 * xre1 ) + ( yim0 * xim1 );
			im1 = ( yim0 * xre1 ) - ( yre0 * xim1 );
			retmp2 = ( realpha * re1 ) + ( imalpha * im1 );
			imtmp2 = ( realpha * im1 ) - ( imalpha * re1 );

			re = retmp1 + retmp2;
			im = imtmp1 + imtmp2;
			idx = ia + ( i0 * sa0 ) + ( i1 * sa1 );
			viewA[ idx ] += re;
			viewA[ idx + 1 ] += im;
			if ( i0 === i1 ) {
				viewA[ idx + 1 ] = 0.0;
			}
		}
	}
	return A;
}


// EXPORTS //

module.exports = zher2;
